import numpy as np
import os, sys
sys.path.append('storage/verity')
try:
    import sqp_core_v2 as sqp2
except Exception:
    sqp2 = None

N = 32

def _seed_grid_minus_corners():
    xs = np.linspace(0.1, 0.9, 6)
    ys = np.linspace(0.1, 0.9, 6)
    centers = []
    for ix, X in enumerate(xs):
        for iy, Y in enumerate(ys):
            if (ix in (0,5)) and (iy in (0,5)):
                continue
            centers.append([X, Y])
    return np.array(centers, dtype=float)

def _load_baseline():
    C = None
    try:
        C = np.load("storage/verity/best_centers.npy")
        if not (isinstance(C, np.ndarray) and C.shape == (N,2)):
            C = None
    except Exception:
        C = None
    if C is None:
        C = _seed_grid_minus_corners()
    return np.clip(C.astype(float), 0.0, 1.0)

def construct_packing() -> tuple:
    if sqp2 is None:
        C = _seed_grid_minus_corners()
        x, y = C[:,0], C[:,1]
        r = np.maximum(1e-8, np.minimum.reduce([x, 1.0-x, y, 1.0-y]))
        print("[SQP v2] fallback: core import failed; returning safe baseline.")
        return C, r

    C = _load_baseline()
    s0, r0 = sqp2.merit_sum_r(C)
    print(f"[SQP v2] start sum={s0:.15f}")

    best_C, best_r, best_s = C.copy(), r0.copy(), float(s0)
    accepts = 0
    noimp = 0
    max_outer = 16
    tau = 0.02
    # Thinned deterministic basis (lighter cost than v1): every 4th circle; alternate offsets
    basis_offsets = [0, 2]
    basis_sel = 0

    for it in range(max_outer):
        basis_idx = list(range(basis_offsets[basis_sel], N, 4))
        improved, C1, R1, S1, tau_new, info = sqp2.step_sqp_v2(
            best_C, tau=tau, basis_idx=basis_idx, h=8e-6, tol_act=5e-16, c1=1e-4
        )
        print(f"[SQP v2] it={it:02d} s0={info['s0']:.15f} s1={info['s_new']:.15f} "
              f"imp={int(info['improved'])} act_pairs={info['n_act_pair']} A={info['A_shape']} "
              f"tau={info['tau']:.3f}->{info['tau_new']:.3f} basis_len={info['basis_len']}")
        tau = tau_new
        basis_sel = 1 - basis_sel

        if improved:
            best_C, best_r, best_s = C1, R1, S1
            accepts += 1
            noimp = 0
        else:
            noimp += 1
            if noimp >= 6:
                break

        if accepts >= 6:
            break

    # Persist only if strictly improved
    if best_s > s0 + 5e-10:
        try:
            os.makedirs("storage/verity", exist_ok=True)
            np.save("storage/verity/best_centers.npy", best_C)
            np.save("storage/verity/best_radii.npy", best_r)
            print(f"[SQP v2] persisted improved packing sum={best_s:.15f}")
        except Exception:
            pass

    return np.array(best_C, dtype=float), np.array(best_r, dtype=float)
